INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Combosquatting dasselbe wie Typosquatting?', 2, '[{"text": "Nein", "correct": true, "because": "Combosquatting fügt Wörter hinzu, Typosquatting nutzt Tippfehler"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Methoden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich als Angreifer mit dieser Technik?', 3, '[{"text": "Nutzer täuschen", "correct": true, "because": "Sieht legitim aus"}, {"text": "Hardware überlasten", "correct": false, "because": "Kein physischer Angriff"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Nicht primär Ransomware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente machen eine solche Domain gefährlich?', 4, '[{"text": "Markenname", "correct": true, "because": "Erzeugt Vertrauen"}, {"text": "Zusätzliches Wort", "correct": true, "because": "Tarnung als legitim"}, {"text": "Falsche TLD", "correct": false, "because": "Nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es nutzt bekannte Marken. b) Es basiert auf Tippfehlern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Typosquatting"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Abwehr dieser Bedrohung?', 4, '[{"text": "URL-Prüfung", "correct": false, "because": "Entscheidend zur Erkennung"}, {"text": "Mitarbeiterschulung", "correct": false, "because": "Wichtig für Awareness"}, {"text": "Serverleistung", "correct": true, "because": "Kein direkter Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob diese Domains immer Malware enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Phishing oder Betrug"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich Malware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode nutze ich, um Nutzer auf so eine Seite zu locken?', 3, '[{"text": "Phishing-E-Mails", "correct": true, "because": "Verbreitet Links effektiv"}, {"text": "SQL-Injection", "correct": false, "because": "Anderer Angriffstyp"}, {"text": "DDoS", "correct": false, "because": "Kein Lockmittel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen schützen vor solchen Angriffen?', 5, '[{"text": "Schulungen", "correct": true, "because": "Erhöht Wachsamkeit"}, {"text": "SSL-Zertifikate", "correct": true, "because": "Authentizität prüfen"}, {"text": "Höhere Bandbreite", "correct": false, "because": "Kein Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Es ist 100-mal häufiger als Typosquatting. b) Es ist leicht erkennbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist schwer zu erkennen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um diese Domains zu erkennen?', 4, '[{"text": "URL-Analyse", "correct": false, "because": "Wichtig für Identifikation"}, {"text": "Markenwissen", "correct": false, "because": "Hilft bei Täuschung"}, {"text": "CPU-Leistung", "correct": true, "because": "Kein direkter Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind solche Domains immer kurzlebig?', 2, '[{"text": "Nein", "correct": true, "because": "Können Jahre aktiv sein"}, {"text": "Ja", "correct": false, "because": "Nicht immer kurzlebig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Keywords sind typisch für solche Domains?', 4, '[{"text": "Support", "correct": true, "because": "Häufig genutzt"}, {"text": "Security", "correct": true, "because": "Weckt Vertrauen"}, {"text": "Speed", "correct": false, "because": "Weniger üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es nur für Phishing genutzt wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Malware oder Betrug"}, {"text": "Ja", "correct": false, "because": "Vielfältige Einsätze"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Abwehr?', 3, '[{"text": "Nutzeraufklärung", "correct": true, "because": "Verhindert Klicks"}, {"text": "Schnelle Server", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Manuelle Updates", "correct": false, "because": "Zu langsam"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es nutzt Emotionen. b) Es ist rein technisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Social Engineering"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet diese Methode Angreifern?', 5, '[{"text": "Hohe Erfolgsrate", "correct": true, "because": "Täuschend echt"}, {"text": "Schwer erkennbar", "correct": true, "because": "Nutzt Vertrauen"}, {"text": "Kostengünstig", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Erkennung unwichtig?', 3, '[{"text": "Domainlänge", "correct": true, "because": "Kein Indikator"}, {"text": "Markenname", "correct": false, "because": "Wichtig für Täuschung"}, {"text": "Zusatzwort", "correct": false, "because": "Teil der Methode"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt es nur bekannte Marken?', 2, '[{"text": "Ja", "correct": true, "because": "Vertrauen ist Schlüssel"}, {"text": "Nein", "correct": false, "because": "Marken sind zentral"}]'),
